ing:clamp(62px,8vw,108px) 0}.head{display:flex;justify-content:space-between;align-items:end;gap:25px;margin-bottom:36px}.head p{max-width:52ch;color:var(--muted);font-size:14px}.note{font-size:11px;color:var(--muted);margin-top:15px}.tag{display:inline-block;border:1px solid currentColor;padding:5px 8px;font-size:9px;letter-spacing:.1em;text-transform:uppercase}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:15px}.card{background:var(--paper);border:1px solid var(--line);padding:23px;min-height:200px;display:flex;flex-direction:column;justify-content:space-between}.card .num{font-size:9px;letter-spacing:.14em;color:var(--accent)}.card h3{font:400 24px var(--serif);margin:24px 0 8px}.card p{color:var(--muted);font-size:13px;margin:0}.price{font-size:12px;font-weight:700;margin-top:13px}.photo img{height:100%;min-height:320px;object-fit:cover}.facts{display:grid;gap:10px;border-top:1px solid var(--line);padding-top:16px;margin-top:24px;font-size:12px}.facts b{display:block;font-size:9px;text-transform:uppercase;letter-spacing:.12em;color:var(--accent)}.booking{background:var(--soft)}.bookgrid{display:grid;grid-template-columns:.8fr 1.2fr;gap:55px;align-items:start}.bookcopy h2{font:400 clamp(36px,4.5vw,58px)/1.05 var(--serif)}.bookcopy p{font-size:14px;color:var(--muted)}.email{display:inline-block;margin:12px 0 0;border-bottom:1px solid;font-weight:700}form{background:var(--paper);padding:clamp(20px,3vw,34px);border:1px solid var(--line)}.fields{display:grid;grid-template-columns:1fr 1fr;gap:14px}.field{display:flex;flex-direction:column;gap:6px}.field.full{grid-column:1/-1}label{font-size:9px;letter-spacing:.12em;text-transform:uppercase;font-weight:700}input,select,textarea{width:100%;padding:12px;border:1px solid var(--line);background:var(--paper);color:var(--ink);font-size:14px}textarea{min-height:92px;resize:vertical}form .btn{width:100%;cursor:pointer}.form-note{font-size:10px;color:var(--muted)}.subhero{padding:45px 0 65px;background:var(--dark);